// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealthz)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/config", wrapper.GetConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/llm/health", wrapper.GetLlmHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/accounts", wrapper.ListTestAccounts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/chat/messages", wrapper.PostChatMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/chat/history", wrapper.GetChatHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/actions", wrapper.CreateAction)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/actions/{action_id}", wrapper.GetAction)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/actions/{action_id}/confirm", wrapper.ConfirmAction)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/actions/{action_id}/cancel", wrapper.CancelAction)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/path", wrapper.GetPath)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/path/steps/{step_id}", wrapper.GetPathStep)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/path/steps/{step_id}/status", wrapper.SetPathStepStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/time-off/config", wrapper.GetTimeOffConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/requests", wrapper.ListRequests)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/access/resources", wrapper.ListAccessResources)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/kb/{slug}", wrapper.GetKbDoc)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/feedback", wrapper.PostFeedback)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/client-events", wrapper.PostClientEvent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/mentor/interns", wrapper.ListMentorInterns)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/mentor/interns/{user_id}/path", wrapper.GetMentorInternPath)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/mentor/access-requests", wrapper.ListMentorAccessRequests)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/mentor/access-requests/{request_id}/decision", wrapper.DecideAccessRequest)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/demo/reset", wrapper.ResetDemo)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/demo/flags", wrapper.ListDemoFlags)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/demo/flags", wrapper.SetDemoFlag)
	})

	return r
}

